function normalizeReviewBasis(value: unknown): ReviewBasis {
  return value === 'environment' ? 'environment' : 'checkpoint';
}

function deriveSessionPhase(status: ReviewRunStatus | null): ReviewSessionPhase {
  switch (status) {
    case 'policy_pending':
