}

function deriveSessionPhase(status: ReviewRunStatus | null): ReviewSessionPhase {
  switch (status) {
    case 'policy_pending':
    case 'policy_ready':
      return 'waiting_on_human';
    case 'running':
      return 'reviewing';
    case 'succeeded':
      return 'completed';
    case 'failed':
      return 'failed';
    case 'cancelled':
      return 'cancelled';
    case 'policy_approved':
    case 'queued':
    default:
      return 'preparing';
  }
}

function deriveStopReason(status: ReviewRunStatus | null): ReviewSessionStopReason | null {
  switch (status) {
    case 'succeeded':
      return 'initial_pass_completed';
    case 'failed':
      return 'initial_pass_failed';
    case 'cancelled':
      return 'cancelled';
    default:
