  const derivedFinishedAt = record.finished_at ?? latestPass?.finishedAt ?? null;

  return {
    id: record.id,
    workspaceId: record.workspace_id,
    anchorDeploymentId: record.anchor_deployment_id,
    repo: record.repo,
    branch: record.branch,
