    : [];
  const readByPath = new Map(relatedReads.map((item) => [item.path, item]));
  relatedFiles = rankedRelated
    .flatMap((item) => {
      const read = readByPath.get(item.path);
      if (!read || read.content === null || read.error) {
        return [];
