    constraints: Array.from(new Set([...(input.agentAnalysis?.intent?.constraints ?? []), ...input.promptConstraints])),
    decisions: Array.from(new Set([...(input.agentAnalysis?.intent?.decisions ?? []), ...input.promptDecisions])),
  });

