      return jsonResponse({ error: 'Anchor deployment not found' }, 404);
    }
    if (deployment.status !== 'succeeded') {
      return jsonResponse(
        {
          error: 'Review session anchor deployment must be succeeded',
          code: 'deployment_not_reviewable',
        },
        409
