        await appendReviewEvent(input.env.DB, {
          reviewId: input.reviewId,
          eventType: 'review_retry_scheduled',
          payload: {
            attemptCount: input.expectedAttemptCount,
            maxRetries: 2,
            reason: 'success_persistence_retry',
