}

export function stripSensitiveTokenFields(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map((item) => stripSensitiveTokenFields(item));
  }
  if (!value || typeof value !== 'object') {
    return value;
  }
  const record = value as Record<string, unknown>;
  return Object.entries(record).reduce<Record<string, unknown>>((result, [key, nested]) => {
    const normalizedKey = key.toLowerCase();
    if (
      normalizedKey === 'x-review-github-token' ||
      normalizedKey === 'review_context_github_token' ||
      normalizedKey === 'x-openrouter-api-key' ||
      normalizedKey === 'openrouter_api_key' ||
      normalizedKey === 'authorization'
    ) {
      return result;
    }
    result[key] = stripSensitiveTokenFields(nested);
    return result;
  }, {});
}

export function withSortedKeys(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map((item) => withSortedKeys(item));
  }
  if (!value || typeof value !== 'object') {
    return value;
  }

  const record = value as Record<string, unknown>;
  return Object.keys(record)
    .sort()
    .reduce<Record<string, unknown>>((result, key) => {
      result[key] = withSortedKeys(record[key]);
      return result;
    }, {});
}

function assignIdempotencyNestedField(
  payload: Record<string, unknown>,
  section: 'policy' | 'format',
  key: string,
  value: unknown
): void {
  payload[section] = {
    ...(payload[section] as Record<string, unknown> | undefined),
    [key]: value,
  };
}

function normalizeEnvironmentRevision(value: unknown):
  | {
      source: 'workspace_head';
      diffSha256: string;
      changedFileCount: number;
      generatedAt: string;
    }
  | undefined {
  if (!isRecord(value)) {
    return undefined;
  }
  const source = typeof value.source === 'string' ? value.source.trim() : '';
  const diffSha256 = typeof value.diffSha256 === 'string' ? value.diffSha256.trim().toLowerCase() : '';
  const changedFileCount =
    typeof value.changedFileCount === 'number' && Number.isFinite(value.changedFileCount)
      ? Math.max(0, Math.floor(value.changedFileCount))
      : 0;
  const generatedAt = typeof value.generatedAt === 'string' ? value.generatedAt.trim() : '';
  if (source !== 'workspace_head') {
    return undefined;
  }
  if (!/^[a-f0-9]{64}$/.test(diffSha256) || !generatedAt) {
    return undefined;
  }
  return {
    source: 'workspace_head',
    diffSha256,
    changedFileCount,
    generatedAt,
  };
}


