    )
  );

  if (changedPaths.length === 0) {
    return {
      source: 'local_git',
      checkpointsRef: 'entire/checkpoints/v1',
      lookbackSessions,
      topN,
      sessionsScanned: 0,
      relatedByChangedPath: {},
    };
  }

  const git = new GitRepo(cwd);
  const checkpointsRef = resolveEntireCheckpointsRef(git);
  if (!checkpointsRef) {
    return null;
  }

