    workspaceId,
    taskId: task.id,
    eventType: 'task_started',
    payload: {
      provider: task.provider,
      model: task.model,
      attemptCount: task.attemptCount,
      maxSteps: task.maxSteps,
    },
  });

  for (let step = 1; step <= task.maxSteps; step += 1) {
    if (await isCancelRequested(env, workspaceId, task.id)) {
