export async function continueReviewSessionAfterSuccessfulPass(
  env: Env,
  review: ReviewRunResponse,
  report: ReviewReport
): Promise<{ nextReviewId: string | null }> {
  if (!review.sessionId) {
    return { nextReviewId: null };
