import type { Env, ReviewBasis, ReviewPolicyMode, ReviewSessionResponse } from '../types.js';
import {
  attachReviewPassToSession,
  appendReviewEvent,
  createReviewRun,
  generateReviewRunId,
  getReviewRunByIdempotency,
  getWorkspace,
  getWorkspaceAccountId,
  getWorkspaceDeployment,
} from './db.js';
import { captureWorkspaceEnvironmentSnapshot, type WorkspaceEnvironmentSnapshot } from './review-runner/environment.js';
import { buildReviewRequestPayload, sha256Hex, stripSensitiveTokenFields } from '../api/reviews/request-shared.js';

export interface CreateReviewSessionPassInput {
  session: ReviewSessionResponse;
  reviewBasis: ReviewBasis;
  policyMode?: ReviewPolicyMode;
  provenance?: Record<string, unknown>;
  policy?: Record<string, unknown>;
  format?: Record<string, unknown>;
  model?: string;
  idempotencyKey?: string;
  environmentSnapshot?: WorkspaceEnvironmentSnapshot | null;
}

export interface CreateReviewSessionPassResult {
  review: import('../types.js').ReviewRunResponse;
  reused: boolean;
  environmentSnapshot: WorkspaceEnvironmentSnapshot | null;
}

export class CreateReviewSessionPassError extends Error {
  constructor(
    message: string,
    public readonly status: number,
    public readonly code?: string
  ) {
    super(message);
    this.name = 'CreateReviewSessionPassError';
  }
}

export async function createReviewSessionPass(
  env: Env,
  input: CreateReviewSessionPassInput
): Promise<CreateReviewSessionPassResult> {
  const session = input.session;
  const reviewBasis = input.reviewBasis;
  const policyMode = input.policyMode ?? 'none';
  const workspace = await getWorkspace(env.DB, session.workspaceId);
  if (!workspace || workspace.status === 'deleted') {
    throw new CreateReviewSessionPassError('Workspace not found', 404, 'workspace_not_found');
  }

  const workspaceAccountId = await getWorkspaceAccountId(env.DB, session.workspaceId);
  if (workspaceAccountId === undefined) {
    throw new CreateReviewSessionPassError('Workspace not found', 404, 'workspace_not_found');
  }

  const deployment = await getWorkspaceDeployment(env.DB, session.workspaceId, session.anchorDeploymentId);
  if (!deployment) {
    throw new CreateReviewSessionPassError('Anchor deployment not found', 404, 'deployment_not_found');
  }
  if (deployment.status !== 'succeeded') {
    throw new CreateReviewSessionPassError('Review session anchor deployment must be succeeded', 409, 'deployment_not_reviewable');
  }

  const environmentSnapshot =
    reviewBasis === 'environment'
      ? (input.environmentSnapshot ??
        (await captureWorkspaceEnvironmentSnapshot(env, {
          id: workspace.id,
          status: workspace.status,
          sandboxId: workspace.sandboxId,
          baselineReady: workspace.baselineReady,
          sourceBundleKey: workspace.sourceBundleKey,
          sourceBundleSha256: workspace.sourceBundleSha256,
        })))
      : null;
  const defaultIdempotencyKey =
    reviewBasis === 'environment' && environmentSnapshot
      ? `review-session-pass:${session.id}:${environmentSnapshot.revision.diffSha256.slice(0, 24)}`
      : `review-session-pass:${session.id}:${session.passCount + 1}`;
  const idempotencyKey = (input.idempotencyKey ?? defaultIdempotencyKey).trim();
  if (!idempotencyKey) {
    throw new CreateReviewSessionPassError('Missing required Idempotency-Key value', 400, 'missing_idempotency_key');
  }

  const { requestPayload, idempotencyPayload } = buildReviewRequestPayload({
    workspaceId: session.workspaceId,
    deploymentId: session.anchorDeploymentId,
    policyMode,
    reviewBasis,
    policy: input.policy ?? {},
    format: input.format ?? {},
    provenance: {
      ...(input.provenance ?? {}),
      repo: session.repo,
      branch: session.branch,
      ...(environmentSnapshot ? { environmentRevision: environmentSnapshot.revision } : {}),
    },
    repo: session.repo,
    branch: session.branch,
    model: input.model,
  });
  const sanitizedRequestPayload = stripSensitiveTokenFields(requestPayload) as Record<string, unknown>;
  const requestPayloadSha256 = await sha256Hex(JSON.stringify(idempotencyPayload));
  const existingReview = await getReviewRunByIdempotency(env.DB, session.workspaceId, idempotencyKey, requestPayloadSha256);
  if (existingReview) {
    return {
      review: existingReview,
      reused: true,
      environmentSnapshot,
    };
  }

  const created = await createReviewRun(env.DB, {
    id: generateReviewRunId(),
    workspaceId: session.workspaceId,
    deploymentId: session.anchorDeploymentId,
    sessionId: session.id,
    targetType: 'workspace_deployment',
    mode: 'report_only',
    idempotencyKey,
    requestPayload: sanitizedRequestPayload,
    requestPayloadSha256,
    accountId: workspaceAccountId,
    provenance: {
      promptSummary:
        reviewBasis === 'environment'
          ? `Environment re-review for session ${session.id}`
          : `Checkpoint re-review for session ${session.id}`,
    },
    repo: session.repo,
    branch: session.branch,
  });

  await attachReviewPassToSession(env.DB, session.id, created.review.id);
  await appendReviewEvent(env.DB, {
    reviewId: created.review.id,
    eventType: 'review_created',
    payload: {
      workspaceId: session.workspaceId,
      deploymentId: session.anchorDeploymentId,
      mode: 'report_only',
      sessionId: session.id,
      reviewBasis,
      environmentRevision: environmentSnapshot?.revision ?? null,
    },
  });

  return {
    review: created.review,
    reused: created.reused,
    environmentSnapshot,
  };
}

import type {
  ReviewBasis,
  ReviewEnvironmentRevision,
  ReviewRunStatus,
  ReviewSessionPassRecord,
  ReviewSessionPassSummary,
  ReviewSessionPhase,
  ReviewSessionRecord,
  ReviewSessionResponse,
  ReviewSessionStopReason,
} from '../../types.js';
import { generatePrefixedId, parseJsonOrFallback } from './reviews/shared.js';

function normalizeReviewBasis(value: unknown): ReviewBasis {
  return value === 'environment' ? 'environment' : 'checkpoint';
}

function normalizeEnvironmentRevision(value: unknown): ReviewEnvironmentRevision | undefined {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return undefined;
  }
  const record = value as Record<string, unknown>;
  if (
    record.source !== 'workspace_head' ||
    typeof record.diffSha256 !== 'string' ||
    !record.diffSha256.trim() ||
    typeof record.changedFileCount !== 'number' ||
    !Number.isFinite(record.changedFileCount) ||
    record.changedFileCount < 0 ||
    typeof record.generatedAt !== 'string' ||
    !record.generatedAt.trim()
  ) {
    return undefined;
  }

  return {
    source: 'workspace_head',
    diffSha256: record.diffSha256.trim(),
    changedFileCount: Math.max(0, Math.floor(record.changedFileCount)),
    generatedAt: record.generatedAt.trim(),
  };
}

function deriveSessionPhase(
  status: ReviewRunStatus | null,
  stopReason: ReviewSessionStopReason | null
): ReviewSessionPhase {
  if (stopReason === 'risky_fix_requires_approval') {
    return 'waiting_on_human';
  }
  if (stopReason === 'auto_remediation_failed') {
    return 'failed';
  }
  switch (status) {
    case 'policy_pending':
    case 'policy_ready':
      return 'waiting_on_human';
    case 'running':
      return 'reviewing';
    case 'succeeded':
      return 'completed';
    case 'failed':
      return 'failed';
    case 'cancelled':
      return 'cancelled';
    case 'policy_approved':
    case 'queued':
    default:
      return 'preparing';
  }
}

function deriveStopReason(status: ReviewRunStatus | null, passCount = 1): ReviewSessionStopReason | null {
  switch (status) {
    case 'succeeded':
      return passCount > 1 ? 'followup_pass_completed' : 'initial_pass_completed';
    case 'failed':
      return passCount > 1 ? 'followup_pass_failed' : 'initial_pass_failed';
    case 'cancelled':
      return 'cancelled';
    default:
      return null;
  }
}

function toPassSummary(record: ReviewSessionPassRecord): ReviewSessionPassSummary {
  const requestPayload = parseJsonOrFallback<Record<string, unknown>>(record.request_payload_json, {});
  const requestProvenance =
    requestPayload.provenance && typeof requestPayload.provenance === 'object' && !Array.isArray(requestPayload.provenance)
      ? (requestPayload.provenance as Record<string, unknown>)
      : {};
  const environmentRevision = normalizeEnvironmentRevision(requestProvenance.environmentRevision);

  return {
    reviewId: record.id,
    status: record.status,
    reviewBasis: normalizeReviewBasis(requestPayload.reviewBasis),
    ...(environmentRevision ? { environmentRevision } : {}),
    createdAt: record.created_at,
    startedAt: record.started_at,
    finishedAt: record.finished_at,
  };
}

function toReviewSessionResponse(record: ReviewSessionRecord, passes: ReviewSessionPassRecord[]): ReviewSessionResponse {
  const passSummaries = passes.map(toPassSummary);
  const latestPass = passSummaries[passSummaries.length - 1] ?? null;
  const currentReviewStatus = latestPass?.status ?? null;
  const derivedPassCount = typeof record.pass_count === 'number' ? record.pass_count : passSummaries.length;
  const derivedUpdatedAt =
    latestPass?.finishedAt ?? latestPass?.startedAt ?? latestPass?.createdAt ?? record.updated_at;
  const derivedFinishedAt = record.finished_at ?? latestPass?.finishedAt ?? null;
  const stopReason = record.stop_reason ?? deriveStopReason(currentReviewStatus, derivedPassCount);

  return {
    id: record.id,
    workspaceId: record.workspace_id,
    anchorDeploymentId: record.anchor_deployment_id,
    repo: record.repo,
    branch: record.branch,
    initialReviewBasis: normalizeReviewBasis(record.initial_review_basis),
    anchorCommitSha: record.anchor_commit_sha,
    anchorCheckpointId: record.anchor_checkpoint_id,
    sourceProjectRoot: record.source_project_root,
    phase: deriveSessionPhase(currentReviewStatus, stopReason),
    passCount: derivedPassCount,
    activeReviewId: record.active_review_id,
    latestReviewId: record.latest_review_id,
    currentReviewStatus,
    stopReason,
    createdAt: record.created_at,
    updatedAt: derivedUpdatedAt,
    finishedAt: derivedFinishedAt,
    passes: passSummaries,
  };
}

export function generateReviewSessionId(): string {
  return generatePrefixedId('session');
}

export async function createReviewSession(
  db: D1Database,
  input: {
    id: string;
    workspaceId: string;
    anchorDeploymentId: string;
    repo: string;
    branch: string;
    initialReviewBasis: ReviewBasis;
    anchorCommitSha?: string | null;
    anchorCheckpointId?: string | null;
    sourceProjectRoot?: string | null;
    accountId?: string | null;
  }
): Promise<ReviewSessionResponse> {
  const now = new Date().toISOString();
  const record = await db
    .prepare(
      `INSERT INTO review_sessions (
         id,
         workspace_id,
         anchor_deployment_id,
         repo,
         branch,
         initial_review_basis,
         anchor_commit_sha,
         anchor_checkpoint_id,
         source_project_root,
         account_id,
         created_at,
         updated_at
       )
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
       RETURNING *`
    )
    .bind(
      input.id,
      input.workspaceId,
      input.anchorDeploymentId,
      input.repo,
      input.branch,
      input.initialReviewBasis,
      input.anchorCommitSha ?? null,
      input.anchorCheckpointId ?? null,
      input.sourceProjectRoot ?? null,
      input.accountId ?? null,
      now,
      now
    )
    .first<ReviewSessionRecord>();

  if (!record) {
    throw new Error('Failed to create review session');
  }

  return toReviewSessionResponse(record, []);
}

export async function attachReviewPassToSession(
  db: D1Database,
  sessionId: string,
  reviewId: string,
  options?: { terminalStatus?: ReviewRunStatus | null }
): Promise<void> {
  const terminalStatus = options?.terminalStatus ?? null;
  const finishedAt = terminalStatus === 'succeeded' || terminalStatus === 'failed' || terminalStatus === 'cancelled'
    ? new Date().toISOString()
    : null;
  await db
    .prepare(
      `UPDATE review_sessions
       SET active_review_id = ?,
           latest_review_id = ?,
           pass_count = CASE
             WHEN latest_review_id IS NULL THEN 1
             WHEN latest_review_id = ? THEN pass_count
             ELSE pass_count + 1
           END,
           stop_reason = ?,
